import{c as t,Q as a,j as o,m as r}from"./chunks/framework.W-g_WCNV.js";const u=JSON.parse('{"title":"Settings","description":"Configure GateKeeper from the admin UI - no restart required.","frontmatter":{"title":"Settings","description":"Configure GateKeeper from the admin UI - no restart required."},"headers":[],"relativePath":"admin/settings.md","filePath":"admin/settings.md"}'),n={name:"admin/settings.md"};function s(i,e,d,l,p,h){return a(),o("div",null,[...e[0]||(e[0]=[r(`<p>The settings page at <code>/settings</code> lets you configure GateKeeper while it is running. All changes apply immediately with no restart.</p><h2 id="access-control" tabindex="-1">Access control <a class="header-anchor" href="#access-control" aria-label="Permalink to &quot;Access control&quot;">​</a></h2><h3 id="allowed-email-domains" tabindex="-1">Allowed email domains <a class="header-anchor" href="#allowed-email-domains" aria-label="Permalink to &quot;Allowed email domains&quot;">​</a></h3><p>A comma-separated list of email domains permitted to log in or be created.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com, contractor.org</span></span></code></pre></div><p>Leave blank to allow any email address. When a domain list is set, attempts from other domains fail with an &quot;invalid credentials&quot; error (indistinguishable from a wrong password, to avoid revealing whether an account exists).</p><h3 id="protected-app-domains" tabindex="-1">Protected app domains <a class="header-anchor" href="#protected-app-domains" aria-label="Permalink to &quot;Protected app domains&quot;">​</a></h3><p>Applies to apps protected with ForwardAuth that live on a different domain than GateKeeper itself.</p><p>After signing in, GateKeeper only returns a user to a destination it trusts. Anything else is refused and the user lands on the GateKeeper home page instead. List your protected apps here so the return trip is allowed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jellyfin.example.net</span></span>
<span class="line"><span>.example.org</span></span></code></pre></div><p>One per line or comma-separated. Each entry covers that domain <strong>and all of its subdomains</strong>, so <code>example.org</code> allows <code>app.example.org</code> and <code>media.example.org</code>. Writing it as <code>.example.org</code>, <code>*.example.org</code>, or pasting a full URL all mean the same thing.</p><p>You do not need an entry for your own GateKeeper domain, your admin domain, or anything under the session cookie domain. Those are always allowed.</p><p>Changes take effect immediately, with no restart.</p><h2 id="session-timeout" tabindex="-1">Session timeout <a class="header-anchor" href="#session-timeout" aria-label="Permalink to &quot;Session timeout&quot;">​</a></h2><p>How many hours a session stays alive after the last authenticated request. Resets on every request, so active users are never logged out. Default is 8 hours, maximum is 720 (30 days).</p><h2 id="password-policy" tabindex="-1">Password policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password policy&quot;">​</a></h2><p>Rules every new password must satisfy. They apply immediately and cover every place a password is set, including passwords an admin sets on someone else&#39;s behalf.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Range</th></tr></thead><tbody><tr><td>Minimum length</td><td>12</td><td>8 to 128</td></tr><tr><td>Require at least one uppercase letter</td><td>Off</td><td>On or off</td></tr><tr><td>Require at least one number</td><td>Off</td><td>On or off</td></tr><tr><td>Require at least one symbol</td><td>Off</td><td>On or off</td></tr></tbody></table><p>The sign-up, reset, and change-password forms all pick up the configured minimum, so what a user sees matches what the server enforces.</p><p>Raising the minimum length generally does more for security than turning on the character requirements. See <a href="/security/password-policy.html">Password policy</a> for the reasoning and for how passwords are hashed.</p><h2 id="smtp" tabindex="-1">SMTP <a class="header-anchor" href="#smtp" aria-label="Permalink to &quot;SMTP&quot;">​</a></h2><p>GateKeeper sends email for two purposes: one-time login codes and password reset links. Without working SMTP, users cannot complete email OTP login or recover their passwords.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Host</td><td>SMTP server hostname, e.g. <code>smtp.fastmail.com</code></td></tr><tr><td>Port</td><td><code>587</code> for STARTTLS, <code>465</code> for TLS, <code>25</code> for plain</td></tr><tr><td>Username</td><td>SMTP authentication username</td></tr><tr><td>Password</td><td>Leave blank to keep the current value</td></tr><tr><td>From address</td><td>The &quot;from&quot; field on all outgoing emails</td></tr><tr><td>TLS mode</td><td><code>STARTTLS</code> (port 587), <code>TLS</code> (port 465), or <code>None</code></td></tr></tbody></table><p>Click <strong>Send test</strong> to verify your SMTP config sends a message to the From address.</p><h2 id="login-page-branding" tabindex="-1">Login page branding <a class="header-anchor" href="#login-page-branding" aria-label="Permalink to &quot;Login page branding&quot;">​</a></h2><p>Customize the appearance of the login, registration, and password reset pages.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>App name</td><td>Shown in the sign-in heading (&quot;Sign in to ...&quot;). Leave blank to show &quot;GateKeeper&quot;.</td></tr><tr><td>Tagline</td><td>Short line of text below the heading on the sign-in page.</td></tr><tr><td>Logo URL</td><td>A public image URL that replaces the GateKeeper mark. Leave blank to keep the default mark.</td></tr></tbody></table><p>When an OIDC client has its own icon configured, that icon takes priority over the logo URL on the sign-in page.</p><h2 id="email-branding" tabindex="-1">Email branding <a class="header-anchor" href="#email-branding" aria-label="Permalink to &quot;Email branding&quot;">​</a></h2><p>Customize the appearance of all outgoing emails (login codes, password resets, and password change notifications).</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Sender name</td><td>Shown in the email header and footer text. Defaults to &quot;GateKeeper&quot;.</td></tr><tr><td>Logo URL</td><td>A public image URL displayed in the email header. Leave blank to show the sender name as text instead.</td></tr><tr><td>Accent color</td><td>Hex color used for the header background and button color. Defaults to <code>#2563eb</code>.</td></tr></tbody></table><p>Changes apply to the next email sent - no restart required.</p><h2 id="oidc-provider" tabindex="-1">OIDC provider <a class="header-anchor" href="#oidc-provider" aria-label="Permalink to &quot;OIDC provider&quot;">​</a></h2><p>Read-only information about GateKeeper&#39;s OIDC configuration:</p><ul><li><strong>Issuer</strong> - the base URL, used as the OIDC issuer identifier</li><li><strong>Discovery</strong> - <code>/.well-known/openid-configuration</code></li><li><strong>Signing</strong> - RS256, keys rotate every 30 days automatically</li></ul><h2 id="forwardauth-snippet" tabindex="-1">ForwardAuth snippet <a class="header-anchor" href="#forwardauth-snippet" aria-label="Permalink to &quot;ForwardAuth snippet&quot;">​</a></h2><p>A ready-to-paste config snippet for protecting apps via ForwardAuth. See the <a href="/integrations/traefik-forwardauth.html">Traefik ForwardAuth integration</a> for the full setup guide.</p><h2 id="unsaved-changes" tabindex="-1">Unsaved changes <a class="header-anchor" href="#unsaved-changes" aria-label="Permalink to &quot;Unsaved changes&quot;">​</a></h2><p>When you edit any field, a sticky save bar appears at the bottom of the page. Click <strong>Save changes</strong> to apply, or <strong>Discard</strong> to revert all edits. Changes are not applied until you save.</p><h2 id="env-var-fallbacks" tabindex="-1">Env var fallbacks <a class="header-anchor" href="#env-var-fallbacks" aria-label="Permalink to &quot;Env var fallbacks&quot;">​</a></h2><p>All settings on this page can be pre-seeded via environment variables (see <a href="/getting-started/configuration.html">Configuration</a>). The UI value always takes precedence over an env var. If no UI value has been saved, the env var value is shown as the default.</p>`,41)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
